import java.util.*;
public class Kruskal {
    int[] parent, rank;
    int find(int x) { return parent[x]==x ? x : (parent[x]=find(parent[x])); }
    boolean union(int x, int y) {
        int rx=find(x), ry=find(y);
        if(rx==ry) return false;
        if(rank[rx]<rank[ry]) parent[rx]=ry; else if(rank[rx]>rank[ry]) parent[ry]=rx; else{parent[ry]=rx;rank[rx]++;}
        return true;
    }
    public List<int[]> mst(int V, int[][] edges) {
        Arrays.sort(edges, (a,b)->a[2]-b[2]);
        parent=new int[V]; rank=new int[V];
        for(int i=0;i<V;i++) parent[i]=i;
        List<int[]> mst=new ArrayList<>();
        for(int[] e:edges) if(union(e[0],e[1])) mst.add(e);
        return mst;
    }
}

